#include <Wire.h>
#include <DHT.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define DHTPIN 2
#define DHTTYPE DHT11

const int RELAY = 7;               // active LOW
const float BATAS_ATAS = 30.0;     // kipas ON di atas suhu ini
const float BATAS_BAWAH = 28.0;    // kipas OFF di bawah suhu ini

DHT dht(DHTPIN, DHTTYPE);
Adafruit_SSD1306 display(128, 64, &Wire, -1);
bool kipasNyala = false;

void setup() {
  pinMode(RELAY, OUTPUT);
  digitalWrite(RELAY, HIGH);       // kipas mati
  dht.begin();
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    while (true);
  }
  display.setTextColor(WHITE);
}

void loop() {
  float t = dht.readTemperature();

  if (!isnan(t)) {
    if (t >= BATAS_ATAS) kipasNyala = true;
    else if (t <= BATAS_BAWAH) kipasNyala = false;
    digitalWrite(RELAY, kipasNyala ? LOW : HIGH);
  }

  display.clearDisplay();
  display.setTextSize(1);
  display.setCursor(0, 0);
  display.println(F("Kipas Otomatis"));

  display.setTextSize(2);
  display.setCursor(0, 20);
  if (isnan(t)) display.print(F("Error"));
  else { display.print(t, 1); display.print(F(" C")); }

  display.setTextSize(1);
  display.setCursor(0, 52);
  display.print(F("Kipas: "));
  display.println(kipasNyala ? F("ON") : F("OFF"));
  display.display();
  delay(2000);
}

questions.question:
Seorang siswa menghubungkan modul relay Active-LOW ke Pin 7. Ia menuliskan kode:
if (t >= 30.0) digitalWrite(7, HIGH); else if (t <= 28.0) digitalWrite(7, LOW);
Bagaimana perilaku kipas yang terhubung ke terminal NO relay tersebut?

questions.question_en:
A student connects an Active-LOW relay module to Pin 7. They write the code:
if (t >= 30.0) digitalWrite(7, HIGH); else if (t <= 28.0) digitalWrite(7, LOW);
How will the fan connected to the relay's NO terminal behave?

questions.question:
Perhatikan potongan kode tanpa penanganan galat sensor berikut:
float t = dht.readTemperature();
if (t >= 30.0) digitalWrite(RELAY, LOW); else digitalWrite(RELAY, HIGH);
Jika kabel data DHT11 terlepas sehingga t bernilai NaN, bagaimana perilaku relay active-LOW tersebut?

questions.question_en:
Consider the following code snippet lacking sensor error handling:
float t = dht.readTemperature();
if (t >= 30.0) digitalWrite(RELAY, LOW); else digitalWrite(RELAY, HIGH);
If the DHT11 data cable is disconnected causing t to be NaN, how will the active-LOW relay behave?

questions.question:
Perhatikan kode pengontrolan OLED SSD1306 berikut:
void loop() {
  float t = dht.readTemperature();
  display.clearDisplay();
  display.setCursor(0,0);
  display.print("Suhu: "); display.print(t);
  delay(1000);
}
Saat diuji, tampilan OLED tetap kosong setelah booting. Mengapa teks tidak muncul di layar?

questions.question_en:
Consider the following SSD1306 OLED control code:
void loop() {
  float t = dht.readTemperature();
  display.clearDisplay();
  display.setCursor(0,0);
  display.print("Suhu: "); display.print(t);
  delay(1000);
}
When tested, the OLED screen remains blank after booting. Why does text fail to appear on screen?

questions.question:
Seorang siswa membuat logika histeresis sebagai berikut:
if (t > 30.0) kipasNyala = true;
if (t < 28.0) kipasNyala = false;
Saat suhu ruangan perlahan naik dari 29.5 °C dan menyentuh tepat 30.0 °C, apa yang terjadi pada status kipas?

questions.question_en:
A student writes the following hysteresis logic:
if (t > 30.0) kipasNyala = true;
if (t < 28.0) kipasNyala = false;
When the room temperature slowly rises from 29.5 °C and reaches exactly 30.0 °C, what happens to the fan state?
